package com.tradingplatform.controller; import com.tradingplatform.paper.*; import com.tradingplatform.paper.PaperDtos.*; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/paper") public class PaperTradingController { private final PaperTradingEngine paper; public PaperTradingController(PaperTradingEngine p){paper=p;} @GetMapping("/account") public Account account(){return paper.account();} @PostMapping("/account/reset") public Account reset(){return paper.reset();} @GetMapping("/orders") public List<Order> orders(){return paper.orders();} @PostMapping("/orders") public ResponseEntity<Order> order(@RequestBody OrderRequest request){Order result=paper.submit(request);return result.status()==PaperOrderStatus.FILLED?ResponseEntity.status(HttpStatus.CREATED).body(result):ResponseEntity.unprocessableEntity().body(result);} @GetMapping("/positions") public List<Position> positions(){return paper.positions();} @PostMapping("/positions/{id}/close") public ResponseEntity<Order> close(@PathVariable UUID id){Order result=paper.close(id);return result.status()==PaperOrderStatus.FILLED?ResponseEntity.status(HttpStatus.CREATED).body(result):ResponseEntity.unprocessableEntity().body(result);} }
